//! This module provides an ID implementation with human friendly representation
//! '<KEY><YYYYMMDD>-<COUNTER>' that is 'domain backwards compatible' with base32hex(UUIDv7)
//! IDs generated by [`id::id()`]. The `<KEY>` prefix is always lowercase.
//!
//! [`IdL`] handles both formats, `Legacy` and `Logic`, correctly, but it generates `Logic` IDs
//! only. Once a domain has `Logic` IDs, newer `Legacy` IDs cannot be added as they will break
//! the domain ordering.
//!
//! The module also includes an `IdLGenerator` for creating new `IdL::Logic` identifiers in a
//! thread-safe manner, ensuring uniqueness and chronological ordering.
//!
//! The DB representation of `Logical` IDs is '<KEY><YYYYMMDD>-<COUNTER>` with `<COUNTER>` being
//! a 10 digit zero padded number.
//!
//! The JSON (REST API) generated representation does not have the `<COUNTER>` padded, but it
//! accepts both.
//!
//! Worker request documents are the exception: the `dxo::yaml` DTOs opt into the padded form
//! through the [`padded`] / [`padded_option`] serde adapters, so a `request.yaml` reads the
//! same whether the supervisor wrote it locally or a kubernetes pod pulled it from the
//! internal `/message` endpoint, and its IDs order as plain strings.
//!
//! Key features:
//! - **Type-safe ID kinds**: `KeyId` trait allows distinguishing different logical IDs at
//!   compile time.
//! - **Structured logical IDs**: Composed of date, key, and counter for better organization.
//! - **Legacy ID support**: `IdL::Legacy` for backward compatibility.
//! - **ID Generation**: `IdLGenerator` for creating new, unique logical IDs.
//! - **Serialization/Deserialization**: Supports `serde` for JSON and `sqlx` for database
//!   interaction, with different padding strategies.

use crate::id;
use crate::id::Id;
use chrono::{NaiveDate, Utc};
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use sqlx::postgres::{PgHasArrayType, PgTypeInfo};
use std::fmt;
use std::hash::{Hash, Hasher};
use std::marker::PhantomData;
use std::str::FromStr;
use std::sync::{Arc, Mutex};
use td_error::{TdError, td_error};

const MAX_KEY_LEN: usize = 3;
const DATE_LEN: usize = 8;

const SEPARATOR: char = '-';
const ID_PADDING: usize = 10;
const MAX_IDL_LEN: usize = MAX_KEY_LEN + DATE_LEN + 1 + ID_PADDING;

/// Errors that can occur when working with logical IDs.
#[td_error]
pub enum IdLError {
    /// The key provided for a `KeyId` is invalid.
    #[error("Invalid KeyId key, it must be 1 to 3 lowercase characters: {0}")]
    InvalidKey(String) = 0,
    /// The given string cannot be parsed into a logical ID.
    #[error("Invalid ID, not Legacy, not '{0}' logical: {1}")]
    CannotParse(String, String) = 1,
}

/// A trait for defining a key that identifies a logical ID type.
///
/// This trait is used to provide a short, unique string identifier for different kinds of
/// logical IDs. The key must be between 1 and 3 lowercase alphabetic characters.
pub trait KeyId: Clone {
    /// Returns the key for the logical ID.
    ///
    /// The key must be 1 to 3 lowercase alphabetic characters.
    fn key() -> &'static str;
}

/// A generic identifier that can be either a modern logical ID (`Logic`) or a legacy ID (`Legacy`).
///
/// `IdL<K>` is designed to provide a unified interface for working with different ID formats.
/// The type parameter `K` must implement the `KeyId` trait, which provides a unique key for each
/// logical ID type.
///
/// When serializing/deserializing, an UNPADDED ID string is used.
/// When encoding/decoding with sqlx, the full PADDED ID string is used.
/// Type K enforces validation during Deserialization.
#[derive(Debug, Clone)]
pub enum IdL<K: KeyId> {
    /// A legacy identifier, based on [`id::id()`], a base32hexnopad(UUIDv7).
    Legacy(String, PhantomData<K>),
    /// New identifier `<KEY><YYYYMMDD>.<COUNTER>`, with counter being 10 digit zero padded.
    Logic(String, PhantomData<K>),
}

impl<K: KeyId> IdL<K> {
    /// Returns `true` if the ID is a `Legacy` variant.
    pub fn is_legacy(&self) -> bool {
        matches!(self, IdL::Legacy(_, _))
    }

    /// Returns `true` if the ID is a `Logic` variant.
    pub fn is_logic(&self) -> bool {
        matches!(self, IdL::Logic(_, _))
    }

    /// Returns the raw string representation of the ID, for `Logic` is always 10 digid zero padded.
    fn raw_str(&self) -> &str {
        match self {
            IdL::Legacy(str, _) => str,
            IdL::Logic(str, _) => str,
        }
    }

    /// Returns the date part of a `Logic` ID as a string slice, if applicable.
    fn date_str(&self) -> Option<&str> {
        match self {
            IdL::Logic(str, _) => Some(&str[K::key().len()..K::key().len() + DATE_LEN]),
            _ => None,
        }
    }

    /// Returns the `NaiveDate` part of a `Logic` ID, if applicable.
    pub fn date(&self) -> Option<NaiveDate> {
        self.date_str()
            .and_then(|s| NaiveDate::parse_from_str(s, "%Y%m%d").ok())
    }

    /// Returns the counter part of a `Logic` ID as a string slice, if applicable.
    fn counter_str(&self) -> Option<&str> {
        match self {
            IdL::Logic(str, _) => Some(&str[K::key().len() + DATE_LEN + 1..]),
            _ => None,
        }
    }

    /// Returns the counter part of a `Logic` ID as a `usize`, if applicable.
    pub fn counter(&self) -> Option<usize> {
        self.counter_str().and_then(|s| s.parse().ok())
    }

    /// Returns the unpadded string representation of the ID.
    ///
    /// For `Logic` IDs, this is the concatenated date, key, and counter without padding.
    /// For `Legacy` IDs, this is the original string.
    pub fn unpadded_str(&self) -> String {
        match self {
            IdL::Legacy(s, _) => s.clone(),
            IdL::Logic(_, _) => {
                format!(
                    "{}{}{SEPARATOR}{}",
                    K::key(),
                    self.date_str().unwrap(),
                    self.counter().unwrap()
                )
            }
        }
    }

    /// Returns the padded string representation of the ID.
    ///
    /// For `Logic` IDs, the counter is padded with leading zeros.
    /// For `Legacy` IDs, this is the original string.
    pub fn padded_str(&self) -> String {
        match self {
            IdL::Legacy(s, _) => s.clone(),
            IdL::Logic(s, _) => s.clone(),
        }
    }

    /// Parses a string into an `IdL<K>`.
    ///
    /// The method first attempts to parse the string as a legacy `Id`. If that fails,
    /// it tries to parse it as a `Logic` ID with the format `<KEY><YYYYMMDD>.<COUNTER>`.
    pub fn parse(s: &str) -> Result<Self, IdLError> {
        // Legacy IDs must be 26 chars, Logical Ids must be between 19 and 21 chars.
        if s.len() == id::ID_LENGTH
            && let Ok(_) = Id::try_from(s)
        {
            return Ok(IdL::Legacy(s.to_string(), PhantomData));
        }

        if s.len() < DATE_LEN + K::key().len() + 1 || s.len() > MAX_IDL_LEN {
            return Err(IdLError::CannotParse(K::key().to_string(), s.to_string()));
        }

        let key_str = s
            .get(0..K::key().len())
            .ok_or_else(|| IdLError::CannotParse(K::key().to_string(), s.to_string()))?;
        let date_str = s
            .get(K::key().len()..K::key().len() + DATE_LEN)
            .ok_or_else(|| IdLError::CannotParse(K::key().to_string(), s.to_string()))?;
        let counter_str = s
            .get(K::key().len() + DATE_LEN + 1..)
            .ok_or_else(|| IdLError::CannotParse(K::key().to_string(), s.to_string()))?;

        let date = NaiveDate::parse_from_str(date_str, "%Y%m%d")
            .map_err(|_| IdLError::CannotParse(K::key().to_string(), s.to_string()))?;

        if !key_str.eq_ignore_ascii_case(K::key()) {
            return Err(IdLError::CannotParse(K::key().to_string(), s.to_string()));
        }

        let counter = usize::from_str(counter_str)
            .map_err(|_| IdLError::CannotParse(K::key().to_string(), s.to_string()))?;

        Ok(Self::new_logic(date, counter))
    }

    /// Creates a new `Legacy` ID from a legacy `Id`.
    pub fn new_legacy(id: Id) -> Self {
        Self::Legacy(id.to_string(), PhantomData)
    }

    /// Creates a new `Logic` ID from a date and a counter.
    pub fn new_logic(date: NaiveDate, counter: usize) -> Self {
        let s = format!(
            "{}{}{SEPARATOR}{:0width$}",
            K::key(),
            date.format("%Y%m%d"),
            counter,
            width = ID_PADDING
        );
        Self::Logic(s, PhantomData)
    }
}

impl<K: KeyId> PartialEq for IdL<K> {
    fn eq(&self, other: &Self) -> bool {
        self.raw_str().eq(other.raw_str())
    }
}

impl<K: KeyId> Eq for IdL<K> {}

#[allow(clippy::non_canonical_partial_ord_impl)]
impl<K: KeyId> PartialOrd for IdL<K> {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        self.raw_str().partial_cmp(other.raw_str())
    }
}

impl<K: KeyId> Ord for IdL<K> {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.raw_str().cmp(other.raw_str())
    }
}

impl<K: KeyId> Hash for IdL<K> {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.raw_str().hash(state)
    }
}

impl<K: KeyId> fmt::Display for IdL<K> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.raw_str())
    }
}

impl<K: KeyId> TryFrom<&String> for IdL<K> {
    type Error = TdError;

    fn try_from(value: &String) -> Result<Self, Self::Error> {
        Ok(Self::parse(value)?)
    }
}

impl<K: KeyId> From<&IdL<K>> for IdL<K> {
    fn from(value: &IdL<K>) -> Self {
        value.clone()
    }
}

// --- IdL: Serialize / Deserialize (Unpadded) ---

impl<K: KeyId> Serialize for IdL<K> {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.unpadded_str())
    }
}

impl<'de, K: KeyId> Deserialize<'de> for IdL<K> {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let value = String::deserialize(deserializer)?;
        Self::parse(&value).map_err(serde::de::Error::custom)
    }
}

// --- IdL: Encode / Decode (Padded) ---
impl<DB: sqlx::Database, K: KeyId> sqlx::Type<DB> for IdL<K>
where
    String: sqlx::Type<DB>,
{
    fn type_info() -> <DB as sqlx::Database>::TypeInfo {
        <String as sqlx::Type<DB>>::type_info()
    }

    fn compatible(ty: &<DB as sqlx::Database>::TypeInfo) -> bool {
        <String as sqlx::Type<DB>>::compatible(ty)
    }
}

impl<'r, DB: sqlx::Database, K: KeyId> sqlx::Decode<'r, DB> for IdL<K>
where
    String: sqlx::Decode<'r, DB>,
{
    fn decode(
        value: <DB as sqlx::Database>::ValueRef<'r>,
    ) -> Result<Self, Box<dyn std::error::Error + 'static + Send + Sync>> {
        let s = <String as sqlx::Decode<'r, DB>>::decode(value)?;
        Ok(Self::parse(&s)?)
    }
}

impl<K: KeyId> PgHasArrayType for IdL<K> {
    fn array_type_info() -> PgTypeInfo {
        PgTypeInfo::with_name("_text")
    }
    fn array_compatible(ty: &PgTypeInfo) -> bool {
        <String as PgHasArrayType>::array_compatible(ty)
    }
}

/// Renders a logical ID in the padded, at-rest form.
///
/// Serde writes the unpadded form, which is the REST representation meant for
/// human consumption. Documents whose IDs are read back as plain strings —
/// the worker request YAMLs — need the padded form instead, so that ordering
/// the string orders the ID. Use it through the [`padded`] and
/// [`padded_option`] serde adapters.
pub trait PaddedIdL {
    fn padded(&self) -> String;
}

impl<K: KeyId> PaddedIdL for IdL<K> {
    fn padded(&self) -> String {
        self.padded_str()
    }
}

/// `#[serde(serialize_with = "td_common::logic_id::padded")]` for a logical ID.
///
/// Serialization only: [`IdL::parse`] already reads both forms back.
pub fn padded<T, S>(value: &T, serializer: S) -> Result<S::Ok, S::Error>
where
    T: PaddedIdL,
    S: Serializer,
{
    serializer.serialize_str(&value.padded())
}

/// [`padded`] for an `Option<logical ID>`.
pub fn padded_option<T, S>(value: &Option<T>, serializer: S) -> Result<S::Ok, S::Error>
where
    T: PaddedIdL,
    S: Serializer,
{
    match value {
        Some(value) => serializer.serialize_some(&value.padded()),
        None => serializer.serialize_none(),
    }
}

/// The internal state of the `IdLGenerator`.
#[derive(Debug)]
struct GeneratorState {
    /// The date of the last generated ID.
    last_date: Option<NaiveDate>,
    /// The counter of the last generated ID.
    counter: usize,
}

/// A thread-safe generator for creating new `IdL<K>` identifiers.
///
/// The generator ensures that each new ID is unique by maintaining an internal counter
/// that is reset daily. It can be initialized with the latest known ID to continue
/// the sequence from that point.
#[derive(Debug, Clone)]
pub struct IdLGenerator<K: KeyId> {
    state: Arc<Mutex<GeneratorState>>,
    _marker: PhantomData<K>,
}

impl<K: KeyId> IdLGenerator<K> {
    /// Creates a new `IdLGenerator`.
    ///
    /// The generator can be initialized with an optional `latest` ID. If `latest` is provided,
    /// the generator will start creating new IDs with a counter value greater than that of `latest`.
    /// If `latest` is `None`, the counter starts at 1.
    ///
    /// # Errors
    ///
    /// Returns an `IdLError::InvalidKey` if the key from `K::key()` is invalid.
    /// Returns an `IdLError::CannotInitializeGenerator` if `latest` is a `Legacy` ID.
    pub fn new(latest: &Option<IdL<K>>) -> Result<Self, IdLError> {
        let key = K::key();

        if key.is_empty()
            || key.chars().count() > MAX_KEY_LEN
            || !key.chars().all(|c| c.is_ascii_lowercase())
        {
            return Err(IdLError::InvalidKey(key.to_string()));
        }

        let (date, counter) = if let Some(latest) = latest {
            if latest.is_legacy() {
                (None, 0)
            } else {
                let last_date = latest.date();
                let counter = latest.counter().unwrap_or(0);
                (last_date, counter)
            }
        } else {
            (None, 0)
        };

        Ok(IdLGenerator {
            state: Arc::new(Mutex::new(GeneratorState {
                last_date: date,
                counter,
            })),
            _marker: PhantomData,
        })
    }
}

impl<K: KeyId> IdLGenerator<K> {
    /// Returns the next sequence number for a given date.
    fn next_sequence(&self, current_date: NaiveDate) -> (NaiveDate, usize) {
        let mut state = self.state.lock().unwrap();

        match state.last_date {
            Some(last) if current_date > last => {
                state.counter = 1;
                state.last_date = Some(current_date);
            }
            Some(_) => {
                state.counter += 1;
            }
            None => {
                state.counter = 1;
                state.last_date = Some(current_date);
            }
        }

        (current_date, state.counter)
    }

    /// Generates a new `IdL<K>` for a specific date.
    fn _generate(&self, current_date: NaiveDate) -> IdL<K> {
        let (date, counter) = self.next_sequence(current_date);
        IdL::new_logic(date, counter)
    }

    /// Generates a new `IdL<K>` using the current UTC date.
    pub fn generate(&self) -> IdL<K> {
        self._generate(Utc::now().date_naive())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{Days, NaiveDate};

    #[derive(Debug, Clone)]
    struct TestKey;
    impl KeyId for TestKey {
        fn key() -> &'static str {
            "tst"
        }
    }

    type TestId = IdL<TestKey>;

    #[test]
    fn test_parse_legacy_id() {
        let id_str = id::id().to_string();
        let id = TestId::parse(&id_str).unwrap();
        assert!(id.is_legacy());
        assert_eq!(id.raw_str(), id_str);
    }

    #[test]
    fn test_parse_logic_id_unpadded() {
        let id_str = "TST20240101-123";
        let id = TestId::parse(id_str).unwrap();
        assert!(id.is_logic());
        assert_eq!(
            id.date().unwrap(),
            NaiveDate::from_ymd_opt(2024, 1, 1).unwrap()
        );
        assert_eq!(id.counter().unwrap(), 123);
        assert_eq!(id.unpadded_str(), "tst20240101-123");
        assert_eq!(id.padded_str(), "tst20240101-0000000123");
    }

    #[test]
    fn test_parse_logic_id_padded() {
        let id_str = "TST20240101-0000000123";
        let id = TestId::parse(id_str).unwrap();
        assert!(id.is_logic());
        assert_eq!(
            id.date().unwrap(),
            NaiveDate::from_ymd_opt(2024, 1, 1).unwrap()
        );
        assert_eq!(id.counter().unwrap(), 123);
        assert_eq!(id.unpadded_str(), "tst20240101-123");
        assert_eq!(id.padded_str(), "tst20240101-0000000123");
    }

    #[test]
    fn test_parse_invalid_short_id() {
        let id_str = "20240101";
        let err = TestId::parse(id_str).unwrap_err();
        assert!(matches!(err, IdLError::CannotParse(_, _)));
    }

    #[test]
    fn test_parse_invalid_date() {
        let id_str = "TST20241301-123"; // Invalid month
        let err = TestId::parse(id_str).unwrap_err();
        assert!(matches!(err, IdLError::CannotParse(_, _)));
    }

    #[test]
    fn test_parse_invalid_key() {
        let id_str = "inv20240101-123";
        let err = TestId::parse(id_str).unwrap_err();
        assert!(matches!(err, IdLError::CannotParse(_, _)));
    }

    #[test]
    fn test_parse_invalid_counter() {
        let id_str = "tst20240101-abc";
        let err = TestId::parse(id_str).unwrap_err();
        assert!(matches!(err, IdLError::CannotParse(_, _)));
    }

    #[test]
    fn test_parse_multibyte_char_does_not_panic() {
        let id_str = "tst2024010\u{20ac}1";
        let err = TestId::parse(id_str).unwrap_err();
        assert!(matches!(err, IdLError::CannotParse(_, _)));
    }

    #[test]
    fn test_generator_new() {
        let generator = IdLGenerator::<TestKey>::new(&None).unwrap();
        let id = generator.generate();
        assert!(id.is_logic());
        assert!(id.date().is_some());
        assert_eq!(id.counter(), Some(1));
    }

    #[test]
    fn test_generator_new_with_same_date() {
        let date = Utc::now().date_naive();
        let latest_id = TestId::new_logic(date, 10);
        let generator = IdLGenerator::<TestKey>::new(&Some(latest_id)).unwrap();
        // using _generate() to ensure we are in the same date
        let id = generator._generate(date);
        assert!(id.is_logic());
        assert_eq!(id.date(), Some(date));
        assert_eq!(id.counter(), Some(11));
    }

    #[test]
    fn test_generator_new_with_newer_date() {
        let generator_date = Utc::now().date_naive();
        let latest_id = TestId::new_logic(generator_date, 10);
        let generator = IdLGenerator::<TestKey>::new(&Some(latest_id)).unwrap();
        let current_date = generator_date.checked_add_days(Days::new(1)).unwrap();
        // using _generate() to ensure we are in the same date
        let id = generator._generate(current_date);
        assert!(id.is_logic());
        assert_eq!(id.date(), Some(current_date));
        assert_eq!(id.counter(), Some(1));
    }

    #[test]
    fn test_generator_new_with_legacy() {
        let latest_id = TestId::Legacy(id::id().to_string(), PhantomData);
        let generator = IdLGenerator::<TestKey>::new(&Some(latest_id)).unwrap();
        let id = generator.generate();
        assert!(id.is_logic());
        assert!(id.date().is_some());
        assert_eq!(id.counter(), Some(1));
    }

    #[test]
    fn test_generator_generate_multiple() {
        let generator = IdLGenerator::<TestKey>::new(&None).unwrap();
        // using _generate() to ensure we are in the same date
        let date = Utc::now().date_naive();
        let id1 = generator._generate(date);
        let id2 = generator._generate(date);
        assert_eq!(id1.date(), id2.date());
        assert_eq!(id1.counter().unwrap() + 1, id2.counter().unwrap());
    }

    #[test]
    fn test_new_logic_creates_logic_variant() {
        let id = TestId::new_logic(NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), 1);
        assert!(id.is_logic());
        assert_eq!(id.padded_str(), "tst20240101-0000000001");
    }

    #[test]
    fn test_serialization() {
        let id = TestId::new_logic(NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), 123);
        let serialized = serde_json::to_string(&id).unwrap();
        assert_eq!(serialized, r#""tst20240101-123""#);
    }

    #[test]
    fn test_deserialization_unpadded() {
        let json = r#""TST20240101-123""#;
        let id: TestId = serde_json::from_str(json).unwrap();
        assert!(id.is_logic());
        assert_eq!(id.counter(), Some(123));
        assert_eq!(id.padded_str(), "tst20240101-0000000123");
    }

    #[test]
    fn test_deserialization_padded() {
        let json = r#""TST20240101-0000000123""#;
        let id: TestId = serde_json::from_str(json).unwrap();
        assert!(id.is_logic());
        assert_eq!(id.counter(), Some(123));
        assert_eq!(id.padded_str(), "tst20240101-0000000123");
    }

    #[test]
    fn test_sqlx_encoding_logic_id() {
        // This is a simplified simulation of what sqlx does.
        // We are testing that encode calls padded_str and decode calls parse.
        let id = TestId::new_logic(NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), 123);
        let encoded_str = id.padded_str();
        assert_eq!(encoded_str, "tst20240101-0000000123");

        let decoded_id = TestId::parse(&encoded_str).unwrap();
        assert_eq!(id, decoded_id);
    }

    #[test]
    fn test_sqlx_encoding_legacy_id() {
        // This is a simplified simulation of what sqlx does.
        let id_str = id::id().to_string();
        let id = TestId::parse(&id_str).unwrap();
        let encoded_str = id.padded_str();
        assert_eq!(encoded_str, id_str);

        let decoded_id = TestId::parse(&encoded_str).unwrap();
        assert_eq!(id, decoded_id);
    }

    #[derive(Serialize)]
    struct PaddedHolder {
        #[serde(serialize_with = "padded")]
        id: TestId,
        #[serde(serialize_with = "padded_option")]
        maybe: Option<TestId>,
    }

    fn logic(counter: usize) -> TestId {
        TestId::new_logic(NaiveDate::from_ymd_opt(2024, 1, 1).unwrap(), counter)
    }

    #[test]
    fn test_padded_adapter_pads_where_plain_serde_does_not() {
        let holder = PaddedHolder {
            id: logic(123),
            maybe: Some(logic(7)),
        };
        assert_eq!(
            serde_json::to_string(&holder).unwrap(),
            r#"{"id":"tst20240101-0000000123","maybe":"tst20240101-0000000007"}"#
        );
        assert_eq!(
            serde_json::to_string(&holder.id).unwrap(),
            r#""tst20240101-123""#
        );
    }

    #[test]
    fn test_padded_option_adapter_keeps_none() {
        let holder = PaddedHolder {
            id: logic(1),
            maybe: None,
        };
        assert_eq!(
            serde_json::to_string(&holder).unwrap(),
            r#"{"id":"tst20240101-0000000001","maybe":null}"#
        );
    }

    #[test]
    fn test_padded_adapter_leaves_legacy_ids_alone() {
        let id_str = id::id().to_string();
        let holder = PaddedHolder {
            id: TestId::parse(&id_str).unwrap(),
            maybe: None,
        };
        assert_eq!(
            serde_json::to_string(&holder).unwrap(),
            format!(r#"{{"id":"{id_str}","maybe":null}}"#)
        );
    }

    #[test]
    fn test_padded_output_orders_as_a_string() {
        let counters = [1usize, 2, 9, 10, 100];

        let padded: Vec<String> = counters.iter().map(|c| logic(*c).padded()).collect();
        let mut padded_sorted = padded.clone();
        padded_sorted.sort();
        assert_eq!(padded, padded_sorted);

        // Which is exactly what the unpadded REST form cannot do.
        let unpadded: Vec<String> = counters.iter().map(|c| logic(*c).unpadded_str()).collect();
        let mut unpadded_sorted = unpadded.clone();
        unpadded_sorted.sort();
        assert_ne!(unpadded, unpadded_sorted);
    }
}
